  "Questo lo gestisce l'ufficio: aprilo dall'area aziendale.": "De asta se ocupă biroul: deschide-o din zona firmei.",
  "Questo è il ruolo operativo assegnato nella commessa; non sostituisce nomine e incarichi di sicurezza. Le fasi descrivono l’avanzamento operativo. Il rapportino dichiara il lavoro; la sua approvazione e il riconoscimento di un SAL sono passaggi distinti.": "Acesta e rolul de lucru dat în comandă; nu înlocuiește numirile și sarcinile de siguranță. Fazele arată cum avansează lucrul. Raportul zilnic declară lucrul făcut; aprobarea lui și recunoașterea unui SAL (situația lucrărilor) sunt pași separați.",
