  "Rileva L, H e P del cassonetto; indica separatamente C, la profondità totale del cielino.": "Măsoară L, H și P ale casetei de rulou; indică separat C, adâncimea totală a capacului inferior.",
  "Rileva il telo, poi verifica guide, rullo, comando e alimentazione del motore.": "Măsoară cortina, apoi verifică ghidajele, axul, acționarea și alimentarea motorului.",
  "Rileva il vano utile, scegli il tipo di apertura e controlla guide, soglia e ingombri.": "Măsoară golul util, alege tipul de deschidere și verifică ghidajele, pragul și gabaritele.",
